var pad = new ArcSignaturePad
{
    Width = 600,
    Signer = "Ada Lovelace",
    InkColor = ArcInkColor.Violet,
    InkWidth = ArcInkWidth.Medium,
    FileName = "ada-signature"
};

pad.StrokesChanged += (_, strokes) => Persist(strokes);
pad.PngSaved += (_, path) => Console.WriteLine($"Saved to {path}");
